    inputImage: none(Image),
    text: block:
      let frameosValue = block:
        js_app_runtime.setDynamicJsAppField(self.node5, "events", block:
          let fieldValue = block:
            let frameosValue = block:
              if cache0.isNone() or epochTime() > cache0Time + 900.0:
                cache0 = some(block:
                  js_app_runtime.getDynamicJsApp(self.node4, context))
                cache0Time = epochTime()
              cache0.get()
            frameosValue.asJson()
          VJson(fieldValue))
        js_app_runtime.getDynamicJsApp(self.node5, context)
      frameosValue.asString(),
    offsetX: 0.0,
    offsetY: 0.0,
    fontColor: parseHtmlColor("#ffffff"),
    fontSize: 32.0,
    borderColor: parseHtmlColor("#000000"),
    overflow: "fit-bounds",
  ))
  scene.node3 = render_imageApp.App(nodeName: "render/image", appKeyword: "render/image", nodeId: 3.NodeId, scene: scene.FrameScene, frameConfig: scene.frameConfig, appConfig: render_imageApp.AppConfig(
    inputImage: none(Image),
    placement: "cover",
